import{_ as e,c as a,a0 as r,o as d}from"./chunks/framework.B6JXc2q-.js";const p=JSON.parse('{"title":"ADR（Architecture Decision Records）","description":"","frontmatter":{},"headers":[],"relativePath":"adr/README.md","filePath":"adr/README.md"}'),i={name:"adr/README.md"};function c(o,t,h,l,n,s){return d(),a("div",null,t[0]||(t[0]=[r('<h1 id="adr-architecture-decision-records" tabindex="-1">ADR（Architecture Decision Records） <a class="header-anchor" href="#adr-architecture-decision-records" aria-label="Permalink to &quot;ADR（Architecture Decision Records）&quot;">​</a></h1><blockquote><p>目录用途：记录重要架构决策、上下文及后续状态 何时读取：引入新边界约束或修改架构规范时</p></blockquote><p>ADR 是决策历史。只有 <strong>Accepted 且未被撤回或取代</strong> 的记录可以作为当前实现依据；Rejected / Withdrawn 仅用于解释历史。</p><h2 id="状态约定" tabindex="-1">状态约定 <a class="header-anchor" href="#状态约定" aria-label="Permalink to &quot;状态约定&quot;">​</a></h2><ul><li>Proposed：提案，尚未生效</li><li>Accepted：已接受并生效</li><li>Rejected：评审后拒绝</li><li>Withdrawn：曾接受或计划实施，后续明确撤回</li><li>Superseded：已被后续 ADR 取代</li></ul><h2 id="决策索引" tabindex="-1">决策索引 <a class="header-anchor" href="#决策索引" aria-label="Permalink to &quot;决策索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>状态</th><th>当前作用</th></tr></thead><tbody><tr><td><a href="./0001-api-boundary.html">0001 API 作为唯一正式边界</a></td><td>Accepted</td><td>WebUI / 外部调用通过 API</td></tr><tr><td><a href="./0002-runtime-ownership.html">0002 Runtime 职责边界</a></td><td>Accepted</td><td>runtime 生命周期与协调职责</td></tr><tr><td><a href="./0003-source-abstraction.html">0003 Source 抽象职责边界</a></td><td>Accepted</td><td>Source 解析边界与注册规则</td></tr><tr><td><a href="./0004-state-authority.html">0004 状态权威单一化</a></td><td>Accepted</td><td>状态 ownership 原则</td></tr><tr><td><a href="./0005-event-model.html">0005 统一事件模型</a></td><td>Withdrawn</td><td>未实施设计的历史记录，不约束当前代码</td></tr><tr><td><a href="./0006-webui-playback-contract.html">0006 WebUI 播放请求与在线搜索引用边界</a></td><td>Accepted</td><td>typed request 与 opaque play reference</td></tr></tbody></table><h2 id="编写要求" tabindex="-1">编写要求 <a class="header-anchor" href="#编写要求" aria-label="Permalink to &quot;编写要求&quot;">​</a></h2><p>文件名使用 <code>NNNN-&lt;short-description&gt;.md</code>。正文至少包含状态、上下文、决策和后果；状态变化时保留原记录并写清变化日期与依据。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../architecture/constraints.html">现行系统约束</a></li><li><a href="./../architecture/system_overview.html">系统总览</a></li></ul>',11)]))}const m=e(i,[["render",c]]);export{p as __pageData,m as default};
